// Trained character n-gram relationship classifier.
//
// Generated by `scripts/train-relationship-nb.py`; do not hand-edit the JSON artifact.
// The model is intentionally small and deterministic: multinomial Naive Bayes over
// Unicode character 1-3 grams. It replaces the fixed Laya relationship question for
// local analysis after passing the held-out corpus gate (currently 95% on 100 rows).
import modelData from "./relationship-nb-model.json";

interface RelationshipNbModel {
  version: string;
  alpha: number;
  temperature: number;
  vocabSize: number;
  docCounts: number[];
  tokenTotals: number[];
  counts: Record<string, number[]>;
  corpusSha256: string;
  features: string;
}

const model = modelData as RelationshipNbModel;

export const RELATIONSHIP_NB_VERSION = model.version;

export const RELATIONSHIP_NB_LABELS = [
  "rejecting", "distant", "neutral", "warm", "romantic",
] as const;

/** Unicode character 1-3 grams, whitespace removed. Must mirror the Python trainer. */
export function relationshipTextGrams(text: string): string[] {
  const compact = Array.from(text).filter((char) => !/\s/u.test(char)).join("");
  const grams: string[] = [];
  for (const size of [1, 2, 3]) {
    for (let index = 0; index + size <= compact.length; index++) {
      grams.push(compact.slice(index, index + size));
    }
  }
  return grams;
}

/** Normalized class probabilities for one relationship text. Deterministic and allocation-bounded. */
export function relationshipTextProbabilities(text: string): Record<string, number> {
  const grams = relationshipTextGrams(text);
  const totalDocs = model.docCounts.reduce((sum, count) => sum + count, 0);
  const scores = model.docCounts.map((docCount) => Math.log(docCount / totalDocs));
  model.docCounts.forEach((_count, labelIndex) => {
    scores[labelIndex] = scores[labelIndex]! - grams.length *
      Math.log(model.tokenTotals[labelIndex]! + model.alpha * model.vocabSize);
  });
  for (const gram of grams) {
    const counts = model.counts[gram];
    for (let labelIndex = 0; labelIndex < scores.length; labelIndex++) {
      scores[labelIndex] = scores[labelIndex]! +
        Math.log((counts?.[labelIndex] ?? 0) + model.alpha);
    }
  }
  const calibrated = scores.map((score) => score / model.temperature);
  const maximum = Math.max(...calibrated);
  const exponents = calibrated.map((score) => Math.exp(score - maximum));
  const total = exponents.reduce((sum, value) => sum + value, 0);
  return Object.fromEntries(RELATIONSHIP_NB_LABELS.map((label, index) =>
    [label, total > 0 ? exponents[index]! / total : 1 / RELATIONSHIP_NB_LABELS.length]));
}
